// src/tokens/index.ts
var STATUS_NAMES = [
  "ok",
  "warning",
  "critical",
  "info",
  "neutral",
  "offline",
  "stale",
  "nodata"
];
var NOTICE_SEVERITIES = ["advisory", "attention", "critical"];
var token = (name, mode = "light") => tokens[mode][name];
var cssVar = (name) => `var(--${name})`;
var statusColor = (status, mode = "light", slot = "base") => token(slot === "base" ? `status-${status}` : `status-${status}-${slot}`, mode);
var noticeColor = (severity, mode = "light", slot = "ink") => token(slot === "ink" ? `notice-${severity}` : `notice-${severity}-${slot}`, mode);
var chartPalette = (mode = "light") => Array.from({ length: 10 }, (_, index) => token(`cat-${index + 1}`, mode));

export { NOTICE_SEVERITIES, STATUS_NAMES, chartPalette, cssVar, noticeColor, statusColor, token, tokens };
